INSERT INTO `assessments` VALUES (1,1,'Pilihlah jawaban yang menurut anda paling benar. Silahkan screenshot hasil dari kuis setelah selesai','\"[{\\\"question\\\":\\\"Platform media sosial TikTok saat ini sangat populer di kalangan pengguna. Dari perspektif HCI, faktor utama yang membuat aplikasi ini sukses adalah...\\\",\\\"options\\\":[\\\"Penggunaan server yang canggih\\\",\\\"Kode pemrograman yang kompleks\\\",\\\"Pemahaman mendalam tentang perilaku dan preferensi pengguna\\\",\\\"Penggunaan algoritma AI terbaru\\\",\\\"Jumlah dana pengembangan yang besar\\\"],\\\"answer\\\":\\\"Pemahaman mendalam tentang perilaku dan preferensi pengguna\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah aplikasi mobile banking memiliki tampilan yang sangat menarik dengan animasi dan grafik yang kompleks, namun beberapa pengguna lansia kesulitan melakukan transaksi dasar. Hal ini menunjukkan bahwa aplikasi tersebut telah memenuhi prinsip utama HCI.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"False\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Seorang pengembang website e-commerce menggunakan warna merah untuk tombol Beli Sekarang dan warna abu-abu untuk tombol Tambah ke Keranjang. Keputusan ini termasuk dalam aspek komputer dari HCI.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"False\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah smart TV terbaru menggunakan kontrol suara sebagai input utama. Hal ini merupakan implementasi dari bidang studi yang mempengaruhi HCI yaitu...\\\",\\\"options\\\":[\\\"Ergonomi\\\",\\\"Psikologi Kognitif\\\",\\\"Linguistik\\\",\\\"Semiotika\\\",\\\"Antropologi\\\"],\\\"answer\\\":\\\"Linguistik\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Di sebuah rumah sakit, sistem informasi yang baru dipasang mengalami penolakan dari para perawat karena merasa sistem terlalu rumit dibanding pencatatan manual. Dari perspektif HCI, hal ini menunjukkan kegagalan dalam...\\\",\\\"options\\\":[\\\"Kapasitas server\\\",\\\"Kecepatan internet\\\",\\\"Human-centered design\\\",\\\"Design thingking\\\",\\\"Usability Testing\\\"],\\\"answer\\\":\\\"Human-centered design\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Jelaskan semua yang sudah anda pahami tentang materi Kuliah Interaksi Manusia Komputer\\\",\\\"options\\\":[\\\"\\\"],\\\"answer\\\":\\\"\\\",\\\"type\\\":\\\"EY\\\"},{\\\"question\\\":\\\"test\\\",\\\"options\\\":[\\\"test\\\",\\\"testtt\\\"],\\\"answer\\\":\\\"testtt\\\",\\\"type\\\":\\\"MC\\\"}]\"',NULL,'2025-03-26 03:00:40.617','2025-03-28 04:39:26.003'),(2,2,'Pilihlah jawaban yang menurut anda paling benar. Silahkan screenshot hasil dari kuis setelah selesai','\"[{\\\"question\\\":\\\"Sebuah aplikasi banking menerapkan fitur autentikasi biometrik (sidik jari/wajah) sebagai alternatif dari password. Dari perspektif Human Factors, hal ini menguntungkan karena...\\\",\\\"options\\\":[\\\"Meningkatkan kecepatan server\\\",\\\"Mengurangi beban kognitif pengguna\\\",\\\"Menghemat ruang penyimpanan\\\",\\\"Meningkatkan bandwidth\\\",\\\"Mengurangi biaya operasional\\\"],\\\"answer\\\":\\\"Mengurangi beban kognitif pengguna\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Aplikasi pembelajaran online menampilkan pesan error 404 - Page Not Found ketika terjadi kesalahan. Hal ini tidak sesuai dengan prinsip desain Human-Centered karena...\\\",\\\"options\\\":[\\\"Menggunakan bahasa teknis\\\",\\\"Terlalu singkat\\\",\\\"Bahasa Asing\\\",\\\"Terlalu panjang\\\",\\\"Menggunakan angka\\\"],\\\"answer\\\":\\\"Menggunakan bahasa teknis\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah website e-commerce menempatkan tombol Checkout di lokasi yang berbeda-beda setiap kali halaman dimuat ulang untuk memberikan variasi tampilan.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"False\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Dalam merancang aplikasi untuk lansia, pengembang menggunakan...\\\",\\\"options\\\":[\\\"Font kecil untuk menghemat ruang\\\",\\\"Warna kontras tinggi dan font besar\\\",\\\"Animasi yang cepat dan dinamis\\\",\\\"Banyak menu tersembunyi\\\",\\\"Suara latar yang keras\\\"],\\\"answer\\\":\\\"Warna kontras tinggi dan font besar\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Seorang desainer membuat form pendaftaran yang meminta pengguna mengisi 20 field dalam satu halaman. Dari perspektif Human Factors, ini bermasalah karena...\\\",\\\"options\\\":[\\\"Terlalu banyak beban server\\\",\\\"Masalah keamanan data\\\",\\\"Overload kognitif pengguna\\\",\\\"Kecepatan internet\\\",\\\"Masalah database\\\"],\\\"answer\\\":\\\"Overload kognitif pengguna\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Jelaskan semua yang sudah anda pahami tentang materi Kuliah Human Factors and Ergonomic Principles in Design Interaction \\\",\\\"options\\\":[\\\"\\\"],\\\"answer\\\":\\\"\\\",\\\"type\\\":\\\"EY\\\"}]\"',NULL,'2025-03-26 03:00:40.984','2025-03-26 03:00:40.984'),(3,3,'Pilihlah jawaban yang menurut anda paling benar. Silahkan screenshot hasil dari kuis setelah selesai','\"[{\\\"question\\\":\\\"Aplikasi mobile banking memiliki fitur keamanan yang sangat ketat dengan 5 langkah verifikasi setiap kali login. Hal ini menunjukkan tingkat usability yang tinggi karena mengutamakan keamanan pengguna.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"False\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah aplikasi pembelajaran online menampilkan pesan error seperti berikut: \\\\\\\"Error code: 0x80070057\\\\\\\". Dari perspektif usability, pesan ini bermasalah karena...\\\",\\\"options\\\":[\\\"Terlalu pendek\\\",\\\"Tidak informatif dan sulit dipahami\\\",\\\"Menggunakan huruf kecil\\\",\\\"Tidak berwarna merah\\\",\\\"Tidak ada suara\\\"],\\\"answer\\\":\\\"Tidak informatif dan sulit dipahami\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Aplikasi pemesanan tiket bioskop memberikan waktu 5 menit untuk menyelesaikan transaksi. Hal ini merupakan implementasi..\\\",\\\"options\\\":[\\\"Efficiency of use\\\",\\\"Memorability\\\",\\\"Learnability\\\",\\\"Satisfaction\\\",\\\"Security\\\"],\\\"answer\\\":\\\"Efficiency of use\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah form pendaftaran yang menampilkan pesan error setelah user selesai mengisi semua field adalah contoh implementasi usability yang baik.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"False\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Website e-learning memberikan badge dan poin untuk setiap tugas yang diselesaikan. Ini meningkatkan usability melalui aspek...\\\",\\\"options\\\":[\\\"Efficiency\\\",\\\"Learnability\\\",\\\"Satisfaction\\\",\\\"Security\\\",\\\"Speed\\\"],\\\"answer\\\":\\\"Satisfaction\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Jelaskan semua yang sudah anda pahami tentang materi Usability\\\",\\\"options\\\":[\\\"\\\"],\\\"answer\\\":\\\"\\\",\\\"type\\\":\\\"EY\\\"}]\"',NULL,'2025-03-26 03:00:41.227','2025-03-26 03:00:41.227'),(4,4,'Pilihlah jawaban yang menurut anda paling benar. Silahkan screenshot hasil dari kuis setelah selesai','\"[{\\\"question\\\":\\\"Seorang pengguna sedang mengisi formulir pendaftaran dalam aplikasi layanan kesehatan. Namun, tidak ada indikator yang menunjukkan apakah sistem sedang memproses data atau tidak. Pengguna merasa bingung apakah formulir telah terkirim atau belum. Prinsip heuristik mana yang tidak diterapkan?\\\",\\\"options\\\":[\\\"Visibility of System Status\\\",\\\"User Control and Freedom\\\",\\\"Consistency and Standards\\\",\\\"Flexibility and Efficiency of Use\\\",\\\"Aesthetic and Minimalist Design\\\"],\\\"answer\\\":\\\"Visibility of System Status\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Dalam sebuah aplikasi mobile, pengguna sering kali tidak sengaja keluar dari aplikasi ketika mencoba menekan tombol “KEMBALI” di halaman pengaturan. Sistem tidak memberikan konfirmasi sebelum keluar. Prinsip mana yang seharusnya diterapkan?\\\",\\\"options\\\":[\\\"Error Prevention\\\",\\\"Help and Documentation\\\",\\\"User Control and Freedom\\\",\\\"Recognition Rather than Recall\\\",\\\"Match between System and the Real World\\\"],\\\"answer\\\":\\\"User Control and Freedom\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah aplikasi e-commerce memiliki menu navigasi yang berbeda di setiap halaman. Hal ini membuat pengguna kesulitan berpindah antar halaman. Prinsip heuristik mana yang dilanggar?\\\",\\\"options\\\":[\\\"Recognition Rather than Recall\\\",\\\"Consistency and Standards\\\",\\\"Visibility of System Status\\\",\\\"Aesthetic and Minimalist Design\\\",\\\"Error Prevention\\\"],\\\"answer\\\":\\\"Consistency and Standards\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah aplikasi bank menggunakan istilah “AUTHENTIFICATION TOKEN” untuk menginformasikan kode OTP kepada pengguna. Banyak pengguna bingung dengan istilah tersebut. Prinsip mana yang seharusnya diterapkan?\\\",\\\"options\\\":[\\\"Flexibility and Efficiency of Use\\\",\\\"Help Users Recognize, Diagnose, and Recover from Errors\\\",\\\"Error Prevention\\\",\\\"Match between System and the Real World\\\",\\\"Consistency and Standards\\\"],\\\"answer\\\":\\\"Match between System and the Real World\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Seorang pelanggan sedang membeli produk melalui aplikasi belanja online. Setelah memasukkan alamat, sistem tiba-tiba menghapus semua data yang telah diisi. Hal ini melanggar prinsip:\\\",\\\"options\\\":[\\\"Error Prevention\\\",\\\"Help and Documentation\\\",\\\"Aesthetic and Minimalist Design\\\",\\\"Visibility of System Status\\\",\\\"Consistency and Standards\\\"],\\\"answer\\\":\\\"Error Prevention\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Jelaskan semua yang sudah anda pahami tentang materi Heuristic Evaluation: Nielsens 10 principles \\\",\\\"options\\\":[\\\"\\\"],\\\"answer\\\":\\\"\\\",\\\"type\\\":\\\"EY\\\"}]\"',NULL,'2025-03-26 03:00:41.423','2025-03-26 03:00:41.423'),(5,5,'Pilihlah jawaban yang menurut anda paling benar. Silahkan screenshot hasil dari kuis setelah selesai','\"[{\\\"question\\\":\\\"Seorang desainer grafis menggunakan aplikasi edit foto, tetapi aplikasi tersebut tidak memiliki tombol “UNDO” untuk membatalkan perubahan. Hal ini melanggar prinsip:\\\",\\\"options\\\":[\\\"User Control and Freedom\\\",\\\"Visibility of System Status\\\",\\\"Aesthetic and Minimalist Design\\\",\\\"Error Prevention\\\",\\\"Recognition Rather than Recall\\\"],\\\"answer\\\":\\\"User Control and Freedom\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Saat login ke aplikasi perbankan, pengguna mendapatkan pesan error: “ERROR 405: ACCESS DENIED”, tanpa penjelasan lebih lanjut. Prinsip mana yang tidak diterapkan?\\\",\\\"options\\\":[\\\"Error Prevention\\\",\\\"Help Users Recognize, Diagnose, and Recover from Errors\\\",\\\"Consistency and Standards\\\",\\\"Visibility of System Status\\\",\\\"Aesthetic and Minimalist Design\\\"],\\\"answer\\\":\\\"Help Users Recognize, Diagnose, and Recover from Errors\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah aplikasi desain grafis memiliki banyak fitur tersembunyi yang hanya dapat diakses dengan shortcut keyboard yang tidak dijelaskan di antarmuka. Prinsip heuristik apa yang diabaikan?\\\",\\\"options\\\":[\\\"Flexibility and Efficiency of Use\\\",\\\"Visibility of System Status\\\",\\\"Help and Documentation\\\",\\\"Recognition Rather than Recall\\\",\\\"Consistency and Standards\\\"],\\\"answer\\\":\\\"Flexibility and Efficiency of Use\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Seorang pengguna ingin mengatur ulang pengaturan aplikasi, tetapi tidak ada panduan atau dokumentasi yang menjelaskan bagaimana cara melakukannya. Prinsip mana yang dilanggar?\\\",\\\"options\\\":[\\\"Help and Documentation\\\",\\\"Consistency and Standards\\\",\\\"Match between System and the Real World\\\",\\\"Recognition Rather than Recall\\\",\\\"Error Prevention\\\"],\\\"answer\\\":\\\"Help and Documentation\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah aplikasi manajemen proyek memiliki terlalu banyak informasi yang ditampilkan dalam satu layar, membuat pengguna kesulitan fokus pada tugas utama. Prinsip mana yang harus diterapkan?\\\",\\\"options\\\":[\\\"Aesthetic and Minimalist Design\\\",\\\"Recognition Rather than Recall\\\",\\\"Help Users Recognize, Diagnose, and Recover from Errors\\\",\\\"Visibility of System Status\\\",\\\"User Control and Freedom\\\"],\\\"answer\\\":\\\"Aesthetic and Minimalist Design\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Jelaskan semua yang sudah anda pahami tentang materi Visual Elements, Information Hierarchy, Consistency, and Interface Readability \\\",\\\"options\\\":[\\\"\\\"],\\\"answer\\\":\\\"\\\",\\\"type\\\":\\\"EY\\\"}]\"',NULL,'2025-03-26 03:00:41.687','2025-03-26 03:00:41.687'),(6,6,'Pilihlah jawaban yang menurut anda paling benar. Silahkan screenshot hasil dari kuis setelah selesai','\"[{\\\"question\\\":\\\"Sebuah aplikasi layanan kesehatan menggunakan latar belakang biru tua dengan teks hitam untuk menampilkan informasi pasien. Beberapa pengguna mengeluh bahwa mereka sulit membaca teks tersebut. Prinsip desain mana yang diabaikan?\\\",\\\"options\\\":[\\\"Visual Hierarchy\\\",\\\"Typography Readability\\\",\\\"Color Contrast\\\",\\\"Recognition Rather than Recall\\\",\\\"User Control and Freedom\\\"],\\\"answer\\\":\\\"Color Contrast\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah situs e-commerce memiliki tombol “CHECKOUT” yang di beberapa halaman ditampilkan sebagai “BAYAR SEKARANG”. Hal ini membuat pengguna bingung. Masalah ini terkait dengan prinsip:\\\",\\\"options\\\":[\\\"Consistency and Standards\\\",\\\"User Control and Freedom\\\",\\\"Information Hierarchy\\\",\\\"Aesthetic and Minimalist Design\\\",\\\"Error Prevention\\\"],\\\"answer\\\":\\\"Consistency and Standards\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah aplikasi berita menggunakan layout yang tidak sejajar, dengan paragraf yang memiliki panjang baris tidak konsisten dan tata letak yang tampak berantakan. Hal ini berkaitan dengan:\\\",\\\"options\\\":[\\\"Information Grouping\\\",\\\"Alignment and Grids\\\",\\\"Whitespace Management\\\",\\\"Recognition Rather than Recall\\\",\\\"Error Prevention\\\"],\\\"answer\\\":\\\"Alignment and Grids\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah aplikasi keuangan menggunakan font dengan ukuran sangat kecil untuk menampilkan laporan transaksi. Hal ini menyebabkan pengguna mengalami kesulitan membaca detail transaksi mereka. Prinsip desain manakah yang tidak diterapkan dengan baik?\\\",\\\"options\\\":[\\\"Typography Readability\\\",\\\"Color Contrast\\\",\\\"Information Hierarchy\\\",\\\"Error Prevention\\\",\\\"Aesthetic and Minimalist Design\\\"],\\\"answer\\\":\\\"Typography Readability\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah situs pendidikan menampilkan judul artikel dengan ukuran lebih kecil dibandingkan isi artikel. Hal ini menyulitkan pengguna dalam menemukan informasi utama. Prinsip desain manakah yang tidak diterapkan dengan baik?\\\",\\\"options\\\":[\\\"User Control and Freedom\\\",\\\"Information Grouping\\\",\\\"Visual Hierarchy\\\",\\\"Recognition Rather than Recall\\\",\\\"Consistency and Standards\\\"],\\\"answer\\\":\\\"Visual Hierarchy\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Dalam sebuah aplikasi mobile banking, tombol “TRANSFER” dan “HAPUS AKUN” memiliki warna yang sama. Hal ini meningkatkan risiko kesalahan pengguna. Prinsip desain manakah yang harus diterapkan?\\\",\\\"options\\\":[\\\"Error Prevention\\\",\\\"Consistency and Standards\\\",\\\"Flexibility and Efficiency of Use\\\",\\\"Help and Documentation\\\",\\\"Aesthetic and Minimalist Design\\\"],\\\"answer\\\":\\\"Error Prevention\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah aplikasi pesan instan menggunakan ikon berbentuk segitiga untuk fitur “BALAS PESAN”, yang tidak umum digunakan dalam aplikasi serupa. Hal ini dapat mengurangi:\\\",\\\"options\\\":[\\\"Consistency and Standards\\\",\\\"Recognition Rather than Recall\\\",\\\"Error Prevention\\\",\\\"Typography Readability\\\",\\\"Information Grouping\\\"],\\\"answer\\\":\\\"Recognition Rather than Recall\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Dalam sebuah aplikasi manajemen proyek, semua elemen ditempatkan sangat berdekatan tanpa ruang kosong yang cukup. Hal ini membuat tampilan terlihat penuh dan sulit dipahami. Apa masalah utama dalam desain ini?\\\",\\\"options\\\":[\\\"Typography Readability\\\",\\\"Color Contrast\\\",\\\"Whitespace Management\\\",\\\"Information Grouping\\\",\\\"User Control and Freedom\\\"],\\\"answer\\\":\\\"Whitespace Management\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah aplikasi berbagi resep makanan menggunakan berbagai jenis font untuk setiap bagian aplikasi, membuat tampilan terlihat tidak profesional dan sulit dibaca. Prinsip mana yang harus diterapkan?\\\",\\\"options\\\":[\\\"Consistency and Standards\\\",\\\"User Control and Freedom\\\",\\\"Aesthetic and Minimalist Design\\\",\\\"Typography Readability\\\",\\\"Information Grouping\\\"],\\\"answer\\\":\\\"Consistency and Standards\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Dalam sebuah situs berita, paragraf utama dan sidebar diletakkan dalam ukuran yang sama, sehingga pengguna sulit membedakan informasi utama dan sekunder. Prinsip desain mana yang tidak diterapkan?\\\",\\\"options\\\":[\\\"Information Grouping\\\",\\\"Visual Hierarchy\\\",\\\"Consistency and Standards\\\",\\\"Recognition Rather than Recall\\\",\\\"Aesthetic and Minimalist Design\\\"],\\\"answer\\\":\\\"Visual Hierarchy\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Jelaskan semua yang sudah anda pahami tentang materi User Centered Design\\\",\\\"options\\\":[\\\"\\\"],\\\"answer\\\":\\\"\\\",\\\"type\\\":\\\"EY\\\"}]\"',NULL,'2025-03-26 03:00:41.890','2025-03-26 03:00:41.890'),(7,7,'Pilihlah jawaban yang menurut anda paling benar. Silahkan screenshot hasil dari kuis setelah selesai','\"[{\\\"question\\\":\\\"Seorang pengguna aplikasi peta digital merasa bingung karena tombol navigasi sering berubah posisi setiap kali memperbesar tampilan peta. Hal ini melanggar prinsip Consistency and Standards.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"True\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah aplikasi perbankan online memberikan pesan error yang hanya bertuliskan “Gagal!” tanpa menjelaskan alasan atau solusi. Ini melanggar prinsip Help Users Recognize, Diagnose, and Recover from Errors.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"True\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Dalam sebuah aplikasi, tombol “Simpan” dan “Hapus” memiliki warna yang sama dan terletak berdampingan, sehingga pengguna sering salah klik. Ini merupakan contoh pelanggaran prinsip Error Prevention.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"True\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Saat pengguna mengisi formulir online, sistem secara otomatis menyimpan progres mereka sehingga mereka tidak kehilangan data jika koneksi terputus. Ini sesuai dengan prinsip Flexibility and Efficiency of Use.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"True\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah situs web e-learning mengharuskan pengguna mengingat kode mata kuliah untuk mencari kursus. Ini melanggar prinsip Recognition Rather than Recall.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"True\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah aplikasi transportasi online menggunakan ikon berbentuk bintang untuk menunjukkan lokasi pengguna saat ini. Pengguna merasa bingung karena biasanya ikon lokasi digambarkan dengan bentuk pin atau titik. Hal ini melanggar prinsip Familiarity dalam Iconography.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"True\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Dalam aplikasi e-commerce, semua elemen ditempatkan sangat berdekatan tanpa ruang kosong yang cukup. Hal ini membuat pengguna kesulitan membedakan bagian produk, harga, dan tombol beli. Ini menunjukkan penggunaan Whitespace yang buruk.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"True\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Seorang desainer menggunakan warna kuning terang untuk teks utama pada latar belakang putih dalam aplikasi e-learning. Hal ini meningkatkan keterbacaan dan memudahkan pengguna membaca konten.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"False\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah aplikasi media sosial menggunakan tombol \\\\\\\"Suka\\\\\\\" dengan ikon hati di beberapa bagian aplikasi, tetapi menggunakan ikon jempol di bagian lainnya untuk fungsi yang sama. Ini melanggar prinsip Consistency and Standards.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"True\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Sebuah aplikasi berita menggunakan font serif untuk teks utama dan font sans-serif untuk judul. Ini merupakan praktik yang baik dalam tipografi.\\\",\\\"options\\\":[\\\"True\\\",\\\"False\\\"],\\\"answer\\\":\\\"True\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Jelaskan semua yang sudah anda pahami tentang materi Implementation of User-centered Design\\\",\\\"options\\\":[\\\"\\\"],\\\"answer\\\":\\\"\\\",\\\"type\\\":\\\"EY\\\"}]\"',NULL,'2025-03-26 03:00:42.232','2025-03-26 03:00:42.232'),(8,8,'Pilihlah jawaban yang menurut anda paling benar. Silahkan screenshot hasil dari kuis setelah selesai','\"[{\\\"question\\\":\\\"Apa yang dimaksud dengan Interaksi Manusia-Komputer (IMK)?\\\",\\\"options\\\":[\\\"Proses komunikasi antara dua komputer\\\",\\\"Proses interaksi antara manusia dan perangkat keras komputer\\\",\\\"Proses interaksi antara manusia dan perangkat lunak komputer\\\",\\\"Proses komunikasi antara manusia dan komputer melalui antarmuka\\\"],\\\"answer\\\":\\\"Proses komunikasi antara manusia dan komputer melalui antarmuka\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Apa yang menjadi tujuan utama dalam desain User Interface (UI)?\\\",\\\"options\\\":[\\\"Membuat perangkat keras komputer lebih efisien\\\",\\\"Mempermudah pengguna dalam berinteraksi dengan sistem\\\",\\\"Proses interaksi antara manusia dan perangkat lunak komputer\\\",\\\"Proses komunikasi antara manusia dan komputer melalui antarmuka\\\"],\\\"answer\\\":\\\"Mempermudah pengguna dalam berinteraksi dengan sistem\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"User Experience (UX) merujuk pada:\\\",\\\"options\\\":[\\\"Bagaimana pengguna merasakan pengalaman mereka selama menggunakan aplikasi\\\",\\\"Desain tampilan antarmuka pengguna\\\",\\\"Penggunaan teknologi dalam pengembangan aplikasi\\\",\\\"Pemrograman perangkat lunak untuk pengguna\\\"],\\\"answer\\\":\\\"Bagaimana pengguna merasakan pengalaman mereka selama menggunakan aplikasi\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Apa yang dimaksud dengan usability dalam konteks desain UI/UX?\\\",\\\"options\\\":[\\\"Pengukuran seberapa mudah dan efisien antarmuka digunakan\\\",\\\"Kualitas grafis yang ditampilkan pada antarmuka\\\",\\\"Jumlah fitur yang ada pada aplikasi\\\",\\\"Kecepatan loading aplikasi\\\"],\\\"answer\\\":\\\"Pengukuran seberapa mudah dan efisien antarmuka digunakan\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Wireframe adalah:\\\",\\\"options\\\":[\\\"Proses pengkodean aplikasi\\\",\\\"Desain awal yang menunjukkan struktur dan elemen utama dari aplikasi\\\",\\\"Proses pengujian aplikasi\\\",\\\"Desain grafis yang menonjolkan warna dan font\\\"],\\\"answer\\\":\\\"Desain awal yang menunjukkan struktur dan elemen utama dari aplikasi\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Jelaskan Apa itu Penelitian\\\",\\\"options\\\":[\\\"\\\"],\\\"answer\\\":\\\"\\\",\\\"type\\\":\\\"EY\\\"},{\\\"question\\\":\\\"Preferensi Pengguna seperti apa yang kalian maksud?\\\",\\\"options\\\":[\\\"\\\"],\\\"answer\\\":\\\"\\\",\\\"type\\\":\\\"EY\\\"},{\\\"question\\\":\\\"Elearning seperti apa yang akan dibangun disini?\\\",\\\"options\\\":[\\\"\\\"],\\\"answer\\\":\\\"\\\",\\\"type\\\":\\\"EY\\\"}]\"',NULL,'2025-03-26 03:00:42.524','2025-03-26 03:00:42.524'),(9,17,'Jawablah dengan tepat','\"[{\\\"question\\\":\\\"Apa jawaban yang benar a atau b?\\\",\\\"options\\\":[\\\"ini adalah jawaban benar\\\",\\\"ini adalah jawaban salah\\\"],\\\"answer\\\":\\\"ini adalah jawaban benar\\\",\\\"type\\\":\\\"MC\\\"},{\\\"question\\\":\\\"Apa yang dimaksud dengan pembelajaran mandiri?\\\",\\\"answer\\\":\\\"Belajar tanpa pengawasan orang lain\\\",\\\"type\\\":\\\"EY\\\"}]\"',NULL,'2025-04-16 14:15:20.879','2025-04-16 14:16:34.798');
